pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, bool ownerRejects) public {
        amount = bound(amount, 0, address(this).balance);
        address attacker;
        if (ownerRejects) {
            attacker = address(new RejectingOwner());
        } else {
            attacker = address(this);
        }
        vm.prank(address(this));
        c = new C();
        vm.deal(address(this), amount);
        if (c.owner() != attacker) {
            vm.prank(c.owner());
            c = new CWithTransferOwner(attacker);
        }
        if (c.owner() != attacker) {
            vm.prank(c.owner());
            c.transferOwnership(attacker);
        }
        if (c.owner() != attacker) {
            return;
        }
        vm.deal(address(this), amount);
        vm.prank(address(this));
        try c.go{value: amount}() {} catch {}
        assertTrue(address(c).balance == 0);
    }
}

contract RejectingOwner {
    fallback() external payable {
        revert("reject");
    }
}

contract CWithTransferOwner is C {
    constructor(address newOwner) {
        owner = payable(newOwner);
    }
    function transferOwnership(address newOwner) external {
        require(msg.sender == owner);
        owner = payable(newOwner);
    }
}
